"""Живая адаптивная вёрстка по обновлённым макетам."""
def opening(en=False):
 def t(ru,eng): return eng if en else ru
 base='../site/assets/gallery/' if en else 'assets/gallery/'
 def visual(file,alt): return f'<div class="new-visual"><img src="{base}{file}" alt="{alt}" loading="lazy"></div>'
 def tiles(items): return '<div class="new-tiles">'+''.join(f'<article><span aria-hidden="true">{icon}</span><h3>{title}</h3><p>{desc}</p></article>' for icon,title,desc in items)+'</div>'
 return '<div class="new-opening">'+f'''<section class="new-screen new-main"><div class="wrap"><div class="new-grid"><div class="new-copy"><p class="eyebrow">{t('Спокойствие начинается с подготовки','Peace of mind starts with preparation')}</p><h1>{t('Правильная аптечка<br>первой помощи<br><em>для важных минут.</em>','A thoughtfully organised<br>home medicine kit.<br><em>Ready when it matters.</em>')}</h1><p class="lead">{t('SAFEBOX — система хранения лекарств с понятной навигацией, печатной инструкцией и доступом к материалам онлайн.','SAFEBOX brings together clear medicine storage, printed information and online learning resources.')}</p><div class="actions"><a class="btn primary" href="choose.html">{t('Выбрать свой комплект','Choose your kit')} →</a><a class="btn" href="video-library.html">▷ {t('Смотреть видео','Explore videos')}</a></div></div>{visual('updated-main.png',t('Семья и концепт бокса SAFEBOX','Family with the SAFEBOX case concept'))}</div>'''+tiles([('◷',t('Быстрая навигация','Clear navigation'),t('Заметные разделы и подписи','Visible sections and labels')),('▤',t('Понятные инструкции','Accessible information'),t('На бумаге и онлайн','In print and online')),('✓',t('Продуманное хранение','Organised storage'),t('У каждого средства своё место','A place for each item')),('♡',t('Для всей семьи','For the whole family'),t('Взрослые и дети','Adults and children'))])+f'''</div></section><section class="new-screen"><div class="wrap"><div class="new-grid"><div class="new-copy"><p class="eyebrow">{t('Понятная навигация','Intuitive navigation')}</p><h2>{t('Откройте SAFEBOX.<br><em>Найдите нужный раздел.</em>','Open SAFEBOX.<br><em>Find the right section.</em>')}</h2><p class="lead">{t('Цвет, символы и крупные подписи помогают ориентироваться. Индивидуальные назначения и инструкции храните рядом со средствами.','Colour, symbols and large labels help you find your way. Keep current individual prescriptions and instructions beside your supplies.')}</p><a class="btn" href="how-it-works.html">{t('Как устроена система','How the system works')} →</a></div>{visual('updated-navigation.png',t('Открытый концепт SAFEBOX и материалы','Open SAFEBOX concept and information resources'))}</div>'''+tiles([('▤',t('Офлайн — в книжке','Offline booklet'),t('Информация под рукой без телефона','Information within reach without a phone')),('▦',t('Онлайн — по ссылке','Online library'),t('Материалы и обучающие видео','Resources and educational videos')),('+',t('Знакомая система','A familiar system'),t('Покажите близким расположение средств','Show your family where supplies are kept'))])+f'''</div></section><section class="new-screen new-urgent"><div class="wrap"><div class="new-grid"><div class="new-copy"><p class="eyebrow">{t('Подготовиться заранее','Prepare in advance')}</p><h2>{t('Когда каждая<br><em>минута важна.</em>','When every<br><em>minute matters.</em>')}</h2><p class="lead">{t('Неожиданная ситуация может произойти дома, на даче или в поездке. Заранее проверьте содержимое аптечки, сохраните назначения и изучите основы первой помощи.','An unexpected situation can arise at home or while travelling. Review your supplies, keep prescriptions accessible and learn first-aid skills in advance.')}</p><a class="btn primary" href="products.html">{t('Начать подготовку','Start preparing')} →</a></div>{visual('updated-response.png',t('Скорая помощь и концепт SAFEBOX','Ambulance and SAFEBOX concept'))}</div><div class="new-callout"><strong>{t('В первые минуты легко растеряться.','It is easy to feel overwhelmed.')}</strong><p>{t('Понятный порядок помогает найти средства и информацию. При экстренной ситуации вызывайте 112 или 103 и следуйте указаниям диспетчера.','Clear organisation helps you find supplies and information. In an emergency, call your local emergency service and follow the dispatcher’s instructions.')}</p></div></div></section></div>'''
